// Types for the generated `stylex.compiled.js`: the same `styles` that
// `stylex.create` returns for `stylex.source.js`, which the compiled file is
// the babel-plugin output of. Without this, tsc inferred the compiled file's
// raw atomic-class objects, which `stylex.props` does not accept.
export declare const styles: typeof import('./stylex.source.js').styles
